INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (2, 31, 1279854983, 'stafficon', 'We are currently hiring for the following staff positions: GameMaster (Level 1), Developer (SQL/Database), and GFX Developer (Graphich design)', 'Now Hiring!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (3, 31, 1280028590, 'newsiteicon', 'Our new website design has been opened for beta release. Please report any problems to our development team.', 'New Website Design');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (4, 31, 1280719790, 'donateicon', 'Testing on the Funserver is ended and it is now officially open for its full launch! New content is being added daily so check back for more updates on our forums!', 'Funserver now open');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (5, 31, 1292387390, 'promocheckicon', 'World of Immortality would like to wish all of its players a Happy Holidays! It may not be Christmas yet but we have already begun rolling out the festivities! For the next two weeks we will be having daily events, rewards and Christmas-themed prizes. Those players who log in during the week of Christmas will also receive free Christmas gifts hand-picked by our staff!', 'Happy Holidays!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (6, 31, 1293769790, 'statsicon', 'World of Immortality would like to wish everyone a Happy New Year! As the last few hours of this year go into the books, we will be counting down the festivities with events, giveaways and prizes for the members of the server!', 'Happy New Year!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (7, 31, 1294720190, 'ucpicon', 'We would like to welcome Torres to our team. As an Event Master, his job will be to plan, design and implement entertaining events for our players. Events are held every day at World of Immortality, and with the addition of Torres we expect many more exciting events to be added to our schedule.', 'Event Master');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (8, 31, 1296707390, 'launchericon', 'World of Immortality would like to welcome back our Egyptian players, who were recently unable to connect due to a nationwide Internet shutdown. Please note that this link provides information on how to obtain slow, yet reliable Internet connectivity should another Internet outage occur. It may not be sufficient for playing WoW, but may nonetheless help keep the channels of communication open between countries.', 'Egypt: Welcome back!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (9, 31, 1300850990, 'statsicon', 'We have now begun our recruiting contest! The rules are simple: Bring your friends, family and others to World of Immortality. The first person to recruit fifteen people to the server will win one FULL DONOR CHARACTER. That is one free level 80 character with best in slot epic gear (Wrathful, Tier 10.5, etc.).', 'Recruiting Contest!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (10, 31, 1372649390, 'ucpicon', '<b>Let me be the first to say a very grateful WELCOME BACK to the loyal and awesome players of World of Immortality! After over a year and a half of waiting, we have finally reopened the best WoW private server in existence!</b>\r\n<br />\r\n<br />\r\nToday is an important day in World of Immortality history. Exactly four years ago today, a small group of WoW players left a buggy, dying server in search of greener pastures. Yet no server offered the stability, the community, and the quality that we desired. And so, World of Immortality was born. For two years we offered the best there was to offer, and over 30,000 users logged on to our servers in that time.\r\n<br />\r\n<br />\r\nSo now, exactly four years after we first brought forth our server, we have finally returned. And we\'ve been busy. We can now offer a server that is more complete, more perfect, and more enjoyable than anything we ever offered before. We offer one low-latency, high-rate realm where balance and quality come first. We welcome you to come and be a part of our continued experiment in excellence. Our realm is currently in testing, but will be accepting new registrations within just a few days. Stay tuned as we keep you updated on all of the new features were adding to World of Immortality. And once again...it\'s great to have you back.', 'We\'re Back!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (11, 31, 1372994990, 'statsicon', '<b>Immortality Reborn has opened its doors! In just 48 hours since our opening, we have already had our first level 80\'s, our first 5-man instances, and many more server firsts achieved by our most hardcore of players.</b>\r\n<br />\r\n<br />\r\nThere are more server firsts to be found, so if you want a chance at greatness, get in game NOW! Just use our Connection Guide link above to get started, and come see what everyone is talking about!', 'Immortality Reborn is Open');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (12, 31, 1373599790, 'promocheckicon', 'We are pleased to announce that we have migrated to our brand new server hardware! The success of the server in it\'s first week and a half has been unprecedented, and the increased population and server scripting has brought about the necessity of truly top-of-the-line server hardware.\r\n<br />\r\n<br />\r\nUntil now our co-owner Orihime has been using her own computer as our temporary host. Orihime\'s work to improve the server is unprecedented, and the server would not have gotten off the ground without her continued work.\r\n<br />\r\n<br />\r\nThe new server hardware is some of the best that we have ever used, and should allow server populations in excess of 1,000 players online. Furthermore, the additional resources allow us to run the test realms needed to quickly improve our already excellent server scripting.\r\n<br />\r\n<br />\r\nIf you haven\'t joined Immortality Reborn yet, NOW is the time! There are still a few server firsts yet just waiting for you to achieve, so get ingame and make a name for yourself!', 'New Hardware!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (13, 31, 1374809390, 'statsicon', 'We are pleased to announce the return of our Promo system! The Promo is a special deal that allows new players to get a character with a boosted level and some level-equivalent gear and gold for free!\r\n<br />\r\n<br />\r\nSimply make a ticket ingame on a new character and say "Promo." After verifying your eligibility, a GM will boost your character to level 70, give you bags, and give you level appropriate epic and heirloom gear help you on your journey to level 80. We will also give you your riding/flying skills and enough gold for spells.\r\n<br />\r\n<br />\r\nPlease note that the Promo is valid for one person per household only, and it is only eligible to people who do not yet have a level 70+ character. If you have any questions feel free to contact a GM ingame', 'New Promo Announced!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (14, 31, 1376969390, 'statsicon', 'We are proud to announce the release of our fully Blizzlike Halls of Reflection encounter! Everything from the spirit waves to the Lich King chase is now fully functional and scripted, and players have already begun attempting this awesome instance.\r\n\r\n\r\nHaven\'t done Halls of Reflection on retail before? Then you\'re in for a treat! Come join us and let us show you what a real development team can do!', 'Halls of Reflection!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (15, 31, 1377574190, 'promocheckicon', 'After multiple deaths, thousands of gold in repair bills, and endless fine-tuning of characters, a group has finally downed the Lich King in 10-man, normal difficulty! Congratulations to Dre and his guild, Chill Capped, as well as Minne from Semper Agricola, for doing the undoable and vanquishing the most dangerous fiend that has been seen on Azeroth thus far.\r\n\r\n\r\nOur fully-scripted Icecrown Citadel instance is quite the challenge, but this group went against all odds to do what many thought was impossible. Congratulations...and good luck on the next step in the journey. Now Heroic Icecrown Citadel, and the Ruby Sanctum, await with yet another level of difficulty and rewards.\r\n\r\n\r\nIf you haven\'t joined Immortality Reborn yet, NOW is the time! We\'re running out of server firsts, so join now and grab your own little piece of glory!', 'The King is Dead!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (16, 31, 1378265390, 'ucpicon', 'We are pleased to announce that our New Player Promotion is continuing! If you have never played on Immortality Reborn, you are eligible to get your first character leveled all the way to 70 for free, along with level-appropriate gear and heirlooms!\r\n\r\n\r\nThe last 10 levels on your journey to level 80 are up to you, but we\'ll give you a heck of a start. You get your riding paid for, cold weather flying, and we\'ll even give you some gold to buy your skills. In a matter of minutes you\'ll be ready to take on Northrend in style!\r\n\r\n\r\nNow remember, the promo is ONLY for brand new characters. If you had a character on Old Immortality, you are welcome to get a promo here. But you can only get the promo once, so choose your character wisely! Just get ingame on the character you want boosted, and make a ticket saying "Promo" to get started!', 'New Promo!');
INSERT INTO `news_posts` (`id`, `poster_id`, `date_posted`, `icon`, `body`, `title`) VALUES (17, 31, 1379129390, 'ucpicon', 'We have decided to extend the New Player Promo indefinitely! This means that new players to the server can receive a free character, boosted to level 70, with heirloom and level-appropriate gear!', 'Promo Continues');
